<?php
namespace App\Http\Controllers; use App\Models\Guest; use App\Models\GuestPhoto; use App\Models\Invitation; use Illuminate\Http\Request;
class PublicInvitationController extends Controller {
 public function show(Request $r,string $slug){$invitation=Invitation::where('slug',$slug)->where('is_published',true)->firstOrFail();$invitation->increment('views_count');$guest=$r->query('g')?Guest::where('invitation_id',$invitation->id)->where('token',$r->query('g'))->first():null;$wishes=$invitation->wishes()->where('is_approved',true)->take(30)->get();$photos=$invitation->photos()->where('status','approved')->take(50)->get();return view('public.invitation',compact('invitation','guest','wishes','photos'));}
 public function rsvp(Request $r,Invitation $invitation){abort_unless($invitation->is_published,404);$d=$r->validate(['token'=>'nullable|string','name'=>'required|max:150','status'=>'required|in:hadir,tidak_hadir,ragu','party_size'=>'required|integer|min:1|max:10','message'=>'nullable|max:1000']);$guest=$d['token']?Guest::where('invitation_id',$invitation->id)->where('token',$d['token'])->first():null;if($guest)$guest->update(['rsvp_status'=>$d['status'],'party_size'=>$d['party_size']]);$invitation->wishes()->create(['guest_name'=>$d['name'],'message'=>$d['message']??'','is_approved'=>true]);return back()->with('ok','RSVP dan ucapan tersimpan.');}
 public function photo(Request $r,Invitation $invitation){abort_unless(in_array($invitation->plan,['premium','pro']),403);$d=$r->validate(['guest_name'=>'required|max:150','photo'=>'required|image|max:8192','caption'=>'nullable|max:255']);$path=$r->file('photo')->store('guest-photos','public');$invitation->photos()->create(['guest_name'=>$d['guest_name'],'path'=>$path,'caption'=>$d['caption']??null,'status'=>'pending']);return back()->with('ok','Foto dikirim dan menunggu moderasi.');}
 public function checkin(Invitation $invitation,Guest $guest){abort_unless($guest->invitation_id===$invitation->id,404);$guest->update(['checked_in_at'=>now()]);return response()->json(['ok'=>true,'guest'=>$guest->name,'checked_in_at'=>$guest->checked_in_at]);}
}
